    for i in range(len(middle_term)):
        result[m + i] += middle_term[i]

    # Add z2 * x^(2m) to the result
    for i in range(len(z2)):
        result[2 * m + i] += z2[i]

    ans = result[:len(A) + len(B) - 1]
    return ans

