        int[] padded_poly = new int[size];
        for (int i = 0; i < poly.Length; i++)
            padded_poly[i] = poly[i];
        return padded_poly;
    }

    // Karatsuba multiplication algorithm for polynomials
    static int[] multiply(int[] A, int[] B)
